// Write src/datasets-data.ts from ../conformance/data/*.csv (exported from the
// R package). Each row is stored as a string of single-digit values.
// Run: npm run gen:datasets
import { readFileSync, writeFileSync } from "node:fs";

const names = ["cafe", "chips", "coffee", "ham", "icecream", "lunchbags", "pies"];
const parts = [
  "// Generated by scripts/gen-datasets.mjs from conformance/data/*.csv. Do not edit.",
  "// Sources and licenses: COPYRIGHTS.",
  "",
  "export const DATA: Record<string, { columns: string[]; rows: string[] }> = {",
];
for (const name of names) {
  const lines = readFileSync(new URL(`../../conformance/data/${name}.csv`, import.meta.url), "utf8")
    .trim().split(/\r?\n/);
  const columns = lines[0].split(",").map((c) => JSON.parse(c));
  const rows = lines.slice(1).map((line) => {
    const cells = line.split(",");
    if (cells.length !== columns.length || cells.some((c) => !/^[0-9]$/.test(c))) {
      throw new Error(`${name}: expected single-digit values`);
    }
    return cells.join("");
  });
  parts.push(`  ${name}: {`);
  parts.push(`    columns: ${JSON.stringify(columns)},`);
  parts.push(`    rows: ${JSON.stringify(rows)},`);
  parts.push("  },");
}
parts.push("};", "");
writeFileSync(new URL("../src/datasets-data.ts", import.meta.url), parts.join("\n"));
console.log("wrote src/datasets-data.ts");
